function removeCookie(name: string) {
  if (!isBrowser) return
  const secure = window.location.protocol === 'https:' ? '; Secure' : ''
  document.cookie = `${name}=; Path=/; Max-Age=0; SameSite=Lax${secure}`
}

export async function seal(key: CryptoKey, plaintext: Uint8Array<ArrayBuffer>, aad?: Uint8Array): Promise<Uint8Array<ArrayBuffer>> {
  const nonce = randomBytes(NONCE_LENGTH)
  const ciphertext = await crypto.subtle.encrypt({ name: 'AES-GCM', iv: nonce, additionalData: aad }, key, plaintext)

func bodyEmail(c fiber.Ctx) string {
  var body struct { Email string `json:"email"` }
  _ = json.Unmarshal(c.Body(), &body)
  if body.Email != "" { return strings.ToLower(strings.TrimSpace(body.Email)) }
  return strings.ToLower(strings.TrimSpace(c.FormValue("email")))
}
